   Design tokens
   ============================================================ */
:root {
  --color-bg:           #0d0d0f;
  --color-surface:      #18181c;
  --color-surface-2:    #222228;
  --color-border:       #2e2e38;
  --color-border-focus: #7c7cf8;

  --color-text:         #e8e8f0;
  --color-text-muted:   #8888a0;

  --color-accent:       #7c7cf8;
  --color-accent-hover: #9a9afb;

  --color-danger:       #e05555;
  --color-danger-hover: #f06060;
  --color-danger-bg:    rgba(224, 85, 85, 0.12);

  --color-overlay:      rgba(0, 0, 0, 0.72);

  --radius-sm:  6px;
  --radius-md:  10px;
  --radius-lg:  16px;

  --shadow-dialog: 0 24px 64px rgba(0, 0, 0, 0.7), 0 4px 16px rgba(0, 0, 0, 0.5);
}

/* ============================================================
   Reset / base
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
  min-height: 100dvh;
}

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  z-index: 9999;
  text-decoration: none;
  transform: translateY(-100%);
  transition: transform 0.15s;
}

.skip-link:focus {
  transform: translateY(0);
}

/* ============================================================
   Header
   ============================================================ */
.site-header {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.site-logo {
  font-size: 1.25rem;
  color: var(--color-accent);
}

.site-name {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--color-text);
}

/* ============================================================
   Main / image preview
   ============================================================ */
main {
  padding: 2.5rem 1.5rem;
  max-width: 860px;
  margin: 0 auto;
}

main:focus {
  outline: none;
}

.image-preview {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* Image frame */
.image-frame {
  width: 100%;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  aspect-ratio: 16 / 9;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Image meta row */
.image-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.image-title {
  font-size: 1.375rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}

.image-details {
  margin-top: 0.375rem;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

/* Image actions */
.image-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
  flex-shrink: 0;
}

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
  font-weight: 600;
  line-height: 1;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  min-height: 44px; /* touch target */
}

.btn:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* Secondary */
.btn-secondary {
  background: var(--color-surface-2);
  color: var(--color-text);
  border-color: var(--color-border);
}

.btn-secondary:hover {
  background: var(--color-border);
  color: var(--color-text);
}

/* Danger */
.btn-danger {
  background: var(--color-danger-bg);
  color: var(--color-danger);
  border-color: rgba(224, 85, 85, 0.35);
}

.btn-danger:hover {
  background: rgba(224, 85, 85, 0.22);
  color: var(--color-danger-hover);
  border-color: rgba(224, 85, 85, 0.55);
}

/* ============================================================
   Dialog — backdrop (via native ::backdrop pseudo-element)
   ============================================================ */
.confirm-dialog::backdrop {
  background: var(--color-overlay);
  backdrop-filter: blur(3px);
}

/* ============================================================
   Dialog — panel
   ============================================================ */
.confirm-dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  color: inherit;
  max-width: 420px;
  width: calc(100% - 2rem);

  /* Centre in viewport */
  position: fixed;
  inset: 0;
  margin: auto;

  /* Hidden by default — shown via .showModal() */
  border-radius: var(--radius-lg);
  overflow: hidden;
}

/* Browser hides <dialog> when closed; reinforce for ::backdrop */
.confirm-dialog:not([open]) {
  display: none;
}

.dialog-inner {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Icon */
.dialog-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  color: var(--color-danger);
  flex-shrink: 0;
}

/* Heading */
.dialog-heading {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.3;
}

/* Body */
.dialog-body {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog-body strong {
  color: var(--color-text);
  font-weight: 600;
}

/* Actions */
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  flex-wrap: wrap;
  margin-top: 0.5rem;
}

/* ============================================================
   Reflow — narrow viewports
   ============================================================ */
@media (max-width: 480px) {
  .image-meta {
    flex-direction: column;
  }

  .image-actions {
    width: 100%;
  }

  .btn {
    flex: 1;
    justify-content: center;
  }

  .dialog-actions {
    flex-direction: column-reverse;
  }

  .dialog-actions .btn {
    width: 100%;
    justify-content: center;
  }
}

/* ============================================================
   Forced colours (high-contrast mode)
   ============================================================ */
@media (forced-colors: active) {
  .btn {
    forced-color-adjust: auto;
    border: 2px solid ButtonText;
  }

  .dialog-inner {
    border: 2px solid ButtonText;
  }

  .dialog-icon {
    forced-color-adjust: none;
    background: Highlight;
    color: HighlightText;
  }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}
