  if (!trigger || !dialog) return;

  /* Open ------------------------------------------------------- */
  trigger.addEventListener('click', () => {
    dialog.showModal();
    // Move initial focus to Cancel, NOT to the destructive button.
    // This prevents accidental deletion via Enter/Space.
    cancelBtn.focus();
  });

  /* Close — Cancel --------------------------------------------- */
  cancelBtn.addEventListener('click', () => {
    dialog.close('cancel');
  });

  /* Close — Confirm (destructive) ------------------------------ */
  confirmBtn.addEventListener('click', () => {
    dialog.close('delete');
    // In a real app, call your delete API here then handle the result.
    // For this demo we just announce the action.
    announceAction('Image deleted from your library.');
  });

  /* Respond to close value ------------------------------------- */
  dialog.addEventListener('close', () => {
    // Native <dialog> automatically restores focus to `trigger`.
    // No manual focus management needed here.
  });

  /* Accessibility: polite live region for status messages ------ */
  function announceAction(message) {
    let liveRegion = document.getElementById('live-region');
